declare class SARequest {
  constructor(method: string, url: string);
  method: string;
  accept(type: string): this;
}

declare namespace request {
  // The TYPE meaning of `Request`: an interface in the namespace half.
  interface Request extends SARequest {}
  interface Static {
    (url: string): Request;
    // The VALUE meaning of `Request`: a property of the const's type.
    Request: typeof SARequest;
    // A name with only a value meaning.
    version: string;
  }
  // A name with only a type meaning.
  interface Opts {
    deep: boolean;
  }
}

declare const request: request.Static;

export = request;
